86		var sb strings.Builder
87	
88		isThinking := r.isThinking
89		if think != nil {
90			isThinking = think.Bool()
91		}
92	
93		if len(tools) > 0 {
94			sb.WriteString(imStartTag + "system\n")
95			sb.WriteString("# Tools\n\nYou have access to the following functions:\n\n<tools>")
96			for _, tool := range tools {
97				sb.WriteString("\n")
98				if b, err := marshalWithSpaces(tool); err == nil {
99					sb.Write(b)
100				}
101			}
102			sb.WriteString(qwen35ToolPostamble)
103			if len(messages) > 0 && messages[0].Role == "system" {
104				systemContent, _ := r.renderContent(messages[0], 0)
105				systemContent = strings.TrimSpace(systemContent)
106				if systemContent != "" {
107					sb.WriteString("\n\n")
108					sb.WriteString(systemContent)
109				}
110			}
111			sb.WriteString(imEndTag + "\n")
112		} else if len(messages) > 0 && messages[0].Role == "system" {
113			systemContent, _ := r.renderContent(messages[0], 0)
114			sb.WriteString(imStartTag + "system\n" + strings.TrimSpace(systemContent) + imEndTag + "\n")
115		}
116	
117		multiStepTool := true
118		lastQueryIndex := len(messages) - 1 // so this is the last user message
119	
120		for i := len(messages) - 1; i >= 0; i-- {
121			message := messages[i]
122			if multiStepTool && message.Role == "user" {
123				content, _ := r.renderContent(message, 0)
124				content = strings.TrimSpace(content)
125				if !(strings.HasPrefix(content, "<tool_response>") && strings.HasSuffix(content, "</tool_response>")) {
126					multiStepTool = false
127					lastQueryIndex = i
128				}
129			}
130		}
131	
132		imageOffset := 0
133		for i, message := range messages {
134			content, nextImageOffset := r.renderContent(message, imageOffset)
135			imageOffset = nextImageOffset
136			content = strings.TrimSpace(content)
137	
138			lastMessage := i == len(messages)-1
139			prefill := lastMessage && message.Role == "assistant"
140	
141			if message.Role == "user" || (message.Role == "system" && i != 0) {
142				sb.WriteString(imStartTag + message.Role + "\n" + content + imEndTag + "\n")
143			} else if message.Role == "assistant" {
144				renderAssistantThinkBlock := r.alwaysRenderAssistantThinkBlock || (isThinking && i > lastQueryIndex)
145				contentReasoning, content := splitQwen35ReasoningContent(content, message.Thinking, renderAssistantThinkBlock)
146	
147				if renderAssistantThinkBlock {
148					sb.WriteString(imStartTag + message.Role + "\n<think>\n" + contentReasoning + "\n</think>\n\n" + content)
149				} else {
150					sb.WriteString(imStartTag + message.Role + "\n" + content)
151				}
152	
153				if len(message.ToolCalls) > 0 {
154					for j, toolCall := range message.ToolCalls {
155						if j == 0 {
156							if strings.TrimSpace(content) != "" {
157								sb.WriteString("\n\n")
158							}
159						} else {
160							sb.WriteString("\n")
161						}
162	
163						sb.WriteString("<tool_call>\n<function=" + toolCall.Function.Name + ">\n")
164						for name, value := range toolCall.Function.Arguments {
165							sb.WriteString("<parameter=" + name + ">\n")
166							sb.WriteString(formatToolCallArgument(value))
167							sb.WriteString("\n</parameter>\n")
168						}
169						sb.WriteString("</function>\n</tool_call>")
170					}
171				}
172	
173				if !prefill {
174					sb.WriteString(imEndTag + "\n")
175				}
176			} else if message.Role == "tool" {
177				if i == 0 || messages[i-1].Role != "tool" {
178					sb.WriteString(imStartTag + "user")
179				}
180				sb.WriteString("\n<tool_response>\n" + content + "\n</tool_response>")
181				if i == len(messages)-1 || messages[i+1].Role != "tool" {
182					sb.WriteString(imEndTag + "\n")
