		p.buffer.WriteString(after)
		if after == "" {
			return true, false
		}
		p.allowLeadingThinkOpenTag = false
		return true, true
	}

	if strings.HasPrefix(qwen35ThinkingOpenTag, trimmed) {
		return true, false
	}

	p.allowLeadingThinkOpenTag = false
	return false, false
}

